static const char *arg(int c,char **v,const char *n){for(int i=2;i+1<c;i++)if(!strcmp(v[i],n))return v[i+1];return NULL;}
static char *slurp(const char *p,size_t *n){FILE*f=fopen(p,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3*d,const char*q){char*e=NULL;int r=sqlite3_exec(d,q,NULL,NULL,&e);if(r!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static int jtext(sqlite3*d,const char*b,size_t n,const char*p,char*out,size_t cap){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,?2)",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,b,(int)n,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,p,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)){snprintf(out,cap,"%s",(const char*)sqlite3_column_text(q,0));ok=*out!='\0';}sqlite3_finalize(q);return ok;}
static int jint(sqlite3*d,const char*b,size_t n,const char*p){sqlite3_stmt*q=NULL;int x=-1;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,?2)",-1,&q,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(q,1,b,(int)n,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,p,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_type(q,0)==SQLITE_INTEGER)x=sqlite3_column_int(q,0);sqlite3_finalize(q);return x;}
static int run(const char *bin,char *const av[],char *path,size_t cap){int fd,status=0;pid_t p;if(snprintf(path,cap,"/tmp/bonfyre-weather-reheat-%ld-XXXXXX",(long)getpid())>=(int)cap||(fd=mkstemp(path))<0)return 0;p=fork();if(p<0){close(fd);unlink(path);return 0;}if(!p){if(dup2(fd,STDOUT_FILENO)<0)_exit(127);close(fd);execv(bin,av);_exit(127);}if(waitpid(p,&status,0)<0||fsync(fd)){close(fd);unlink(path);return 0;}close(fd);return WIFEXITED(status)&&WEXITSTATUS(status)==0;}
static int seen(sqlite3*d,const char*delta,const char*source){sqlite3_stmt*q=NULL;int x=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM material_weather_reheat_receipt WHERE delta_id=?1 AND source_ref=?2",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,source,-1,SQLITE_TRANSIENT);x=sqlite3_step(q)==SQLITE_ROW;sqlite3_finalize(q);return x;}
static int mark(sqlite3*d,const char*delta,const char*source){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT INTO material_weather_reheat_receipt(delta_id,source_ref,processed_at) VALUES(?1,?2,?3)",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,source,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(q,3,(sqlite3_int64)time(NULL));ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);return ok;}
int main(int argc,char **argv){const char*dbp=arg(argc,argv,"--db"),*gate=arg(argc,argv,"--weather-gate"),*gdb=arg(argc,argv,"--gate-db"),*address=arg(argc,argv,"--address-db"),*lease=arg(argc,argv,"--lease-db"),*weather=arg(argc,argv,"--weather"),*delta_path=arg(argc,argv,"--delta"),*acquire=arg(argc,argv,"--acquire-dir"),*cancel=arg(argc,argv,"--cancel-dir"),*out=arg(argc,argv,"--out-dir"),*raw=arg(argc,argv,"--limit");sqlite3*d=NULL,*m=NULL;sqlite3_stmt*q=NULL;char*body=NULL,*gate_body=NULL,delta[256]={0},schema[96]={0},truth[96]={0},declared[512]={0};size_t n=0,gn=0;int limit=raw?atoi(raw):256,targeted=0,processed=0,already=0,admitted=0,refreshed=0,held=0,cancelled=0,pending_examined=0,ok=0;
 enum{WR_REHEAT};static const BfCommandEntry reheat_commands[]={{"reheat",WR_REHEAT,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(reheat_commands,sizeof(reheat_commands)/sizeof(reheat_commands[0]),argv[1]);if(argc<2||!command||command->id!=WR_REHEAT||!dbp||!gate||!gdb||!address||!lease||!weather||!delta_path||!out){fputs("usage: bonfyre-material-weather-reheat reheat --db DB --weather-gate BIN --gate-db DB --address-db DB --lease-db DB --weather JSON --delta FACTDELTA --acquire-dir DIR --cancel-dir DIR --out-dir DIR [--limit N]\n",stderr);return 2;}if(limit<1)limit=1;if(limit>4096)limit=4096;if(!(body=slurp(delta_path,&n))||sqlite3_open(dbp,&d)!=SQLITE_OK||sqlite3_open(":memory:",&m)!=SQLITE_OK||!sql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS material_weather_reheat_receipt(delta_id TEXT NOT NULL,source_ref TEXT NOT NULL,processed_at INTEGER NOT NULL,PRIMARY KEY(delta_id,source_ref));")||!jtext(m,body,n,"$.schema",schema,sizeof(schema))||strcmp(schema,"bonfyre-fact-delta.v1")||!jtext(m,body,n,"$.delta_id",delta,sizeof(delta))||!jtext(m,body,n,"$.truth",truth,sizeof(truth))||strcmp(truth,"source_standing_changed_only")||!jtext(m,body,n,"$.source",declared,sizeof(declared)))goto done;
 if(sqlite3_prepare_v2(m,"SELECT DISTINCT substr(value,17) FROM json_each(?1,'$.writes') WHERE typeof(value)='text' AND substr(value,1,16)='ResourceWeather:' ORDER BY 1 LIMIT ?2",-1,&q,NULL)!=SQLITE_OK)goto done;sqlite3_bind_text(q,1,body,(int)n,SQLITE_TRANSIENT);sqlite3_bind_int(q,2,limit);while(sqlite3_step(q)==SQLITE_ROW){const char*source=(const char*)sqlite3_column_text(q,0);char tmp[128]={0};char*av[]={(char*)gate,"drain","--db",(char*)gdb,"--address-db",(char*)address,"--lease-db",(char*)lease,"--weather",(char*)weather,"--acquire-dir",(char*)(acquire?acquire:""),"--cancel-dir",(char*)(cancel?cancel:""),"--out-dir",(char*)out,"--source",(char*)source,"--refresh-id",delta,"--limit","4096",NULL};if(!source||!*source||strcmp(source,declared))goto done;targeted++;if(seen(d,delta,source)){already++;continue;}if(!run(gate,av,tmp,sizeof(tmp))||!(gate_body=slurp(tmp,&gn))){unlink(tmp);goto done;}unlink(tmp);if(jint(m,gate_body,gn,"$.admitted")<0||jint(m,gate_body,gn,"$.refreshes_emitted")<0||jint(m,gate_body,gn,"$.held")<0||jint(m,gate_body,gn,"$.pending_cancelled")<0||jint(m,gate_body,gn,"$.pending_examined")<0)goto done;admitted+=jint(m,gate_body,gn,"$.admitted");refreshed+=jint(m,gate_body,gn,"$.refreshes_emitted");held+=jint(m,gate_body,gn,"$.held");cancelled+=jint(m,gate_body,gn,"$.pending_cancelled");pending_examined+=jint(m,gate_body,gn,"$.pending_examined");free(gate_body);gate_body=NULL;if(!mark(d,delta,source))goto done;processed++;}
 if(targeted==0)goto done;printf("{\"delta_id\":\"%s\",\"targeted_sources\":%d,\"processed\":%d,\"already_processed\":%d,\"admitted\":%d,\"refreshes_emitted\":%d,\"held\":%d,\"pending_cancelled\":%d,\"pending_intents_examined\":%d,\"truth\":\"resource_weather_fact_delta_reheats_only_matching_pending_intent\",\"cannot_infer\":[\"weather change -> authority\",\"admitted or refreshed -> observed body\",\"held intent -> global scan\"]}\n",delta,targeted,processed,already,admitted,refreshed,held,cancelled,pending_examined);ok=1;
done:sqlite3_finalize(q);if(m)sqlite3_close(m);if(d)sqlite3_close(d);free(body);free(gate_body);return ok?0:1;}
